/* @lc app=leetcode id=3020 lang=kotlin */ class Solution { fun maximumLength(nums: IntArray): Int = nums.toList().groupingBy { it.toLong() }.eachCount().let { c -> maxOf(c[1L]?.let { if (it % 2 == 1) it else it - 1 } ?: 1, c.keys.filter { it != 1L }.maxOfOrNull { x -> generateSequence(x) { v -> (v * v).takeIf { c[v]!! >= 2 && c.containsKey(it) } }.count().let { 2 * it - 1 } } ?: 1) } }